import {
  AbsoluteFill,
  Sequence,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { AdProps, BRAND, FONT_STACK, layoutFor, SkillTier } from "../theme";
import { BrandBackground } from "../components/BrandBackground";
import { Caption } from "../components/Caption";
import { PlayerChip } from "../components/PlayerChip";
import { AdCtaOutro } from "../components/AdCtaOutro";
import { AdAudio, Sfx } from "../components/AdAudio";

/** Voiceover cues — files generated by scripts/gen-vo.mjs (mm_* lines). */
const VO_LINES = [
  { at: 8, file: "mm_hook" },
  { at: 96, file: "mm_casual" },
  { at: 200, file: "mm_social" },
  { at: 305, file: "mm_standard" },
  { at: 410, file: "mm_competitive" },
  { at: 516, file: "mm_propick" },
  { at: 660, file: "mm_outro" },
];

type P = {
  name: string;
  rating: number;
  skill: SkillTier;
  /** partner this player repeats with (index into QUEUE) — drives link lines */
  linkTo?: number;
};

/** Same queue for every mode — the ad's whole point is "same input,
 *  different draft". Two rival lanes: winners bracket vs losers bracket.
 *  Eli/Fay are high-rated losers (lost with weak partners) — they exist
 *  so Pro Pick can visibly reach across the lane for them. */
const QUEUE: P[] = [
  { name: "Marco", rating: 4.6, skill: "advanced", linkTo: 1 },
  { name: "Liza", rating: 4.2, skill: "advanced" },
  { name: "Jun", rating: 3.9, skill: "intermediate", linkTo: 3 },
  { name: "Rhea", rating: 3.5, skill: "intermediate" },
  { name: "Tito", rating: 4.4, skill: "advanced" },
  { name: "Nadia", rating: 4.0, skill: "intermediate" },
  { name: "Sam", rating: 3.0, skill: "intermediate" },
  { name: "Ed", rating: 2.6, skill: "beginner" },
];

type Lane = {
  label: string;
  icon: string;
  color: string;
  idxs: number[];
};

/** Lane membership as QUEUE indices — mirrors queueType WINNERS/LOSERS */
const LANES: Lane[] = [
  { label: "WINNERS", icon: "🏆", color: BRAND.gold, idxs: [0, 1, 2, 3] },
  { label: "LOSERS", icon: "🔁", color: "#f472b6", idxs: [4, 5, 6, 7] },
];

/** Pro Pick ignores brackets — one pool. Chips start in queue order,
 *  then visibly sort by rating before the top-4 draft. */
const POOL_LANE: Lane[] = [
  {
    label: "POOL",
    icon: "⚡",
    color: BRAND.gold,
    idxs: [0, 1, 2, 3, 4, 5, 6, 7],
  },
];
/** Rating-descending order the pool animates into */
const POOL_SORTED = [0, 4, 1, 5, 2, 3, 6, 7];
const POOL_COLS = 4;

type Mode = {
  key: string;
  name: string;
  /** the mood/question this mode answers — headline of the beat */
  mood: string;
  rated: boolean;
  /** queue indices drafted */
  pick: number[];
  /** teamA/teamB as queue indices (subset of pick) */
  teamA: number[];
  teamB: number[];
  /** 0–3 dial levels */
  balance: number;
  variety: number;
  /** draft ignores queue order — chips jump the line */
  poolSkip?: boolean;
  /** draw "played together" link lines before the split */
  showLinks?: boolean;
};

const MODES: Mode[] = [
  {
    key: "casual",
    name: "Casual",
    mood: "Just here to chill?",
    rated: false,
    // winners bracket outranks losers on priority → all 4 drafted there
    pick: [0, 1, 2, 3],
    teamA: [0, 3],
    teamB: [1, 2],
    balance: 3,
    variety: 0,
  },
  {
    key: "social",
    name: "Social",
    mood: "Bored of the same faces?",
    rated: false,
    pick: [0, 1, 2, 3],
    // linked pairs (0↔1, 2↔3) split across teams — variety over balance
    teamA: [0, 2],
    teamB: [1, 3],
    balance: 1,
    variety: 3,
    showLinks: true,
  },
  {
    key: "standard",
    name: "Standard",
    mood: "Want it fair and fresh?",
    rated: true,
    pick: [0, 1, 2, 3],
    teamA: [0, 3],
    teamB: [1, 2],
    balance: 2,
    variety: 2,
    showLinks: true,
  },
  {
    key: "competitive",
    name: "Competitive",
    mood: "Ready to sweat?",
    rated: true,
    pick: [0, 1, 2, 3],
    teamA: [0, 3],
    teamB: [1, 2],
    balance: 3,
    variety: 2,
    showLinks: true,
  },
  {
    key: "propick",
    name: "Pro Pick",
    mood: "Chasing the perfect game?",
    rated: true,
    // ignores lanes — top 4 by rating reach across the losers bracket
    pick: [0, 1, 4, 5],
    teamA: [0, 5],
    teamB: [1, 4],
    balance: 3,
    variety: 1,
    poolSkip: true,
  },
];

const teamRating = (idxs: number[]) =>
  idxs.reduce((s, i) => s + QUEUE[i].rating, 0);

/** Two segmented dials — the at-a-glance differentiator per mode. */
const Dials: React.FC<{
  mode: Mode;
  scale: number;
  startFrame: number;
}> = ({ mode, scale, startFrame }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const fill = spring({
    frame: frame - startFrame,
    fps,
    config: { damping: 16, stiffness: 160 },
  });
  const dial = (label: string, level: number, active: string) => (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 10 * scale,
      }}
    >
      <div
        style={{
          fontFamily: FONT_STACK,
          fontWeight: 800,
          fontSize: 20 * scale,
          color: "rgba(255,255,255,0.7)",
          letterSpacing: 2,
        }}
      >
        {label}
      </div>
      {[0, 1, 2].map((i) => (
        <div
          key={i}
          style={{
            width: 26 * scale,
            height: 26 * scale,
            borderRadius: "50%",
            background: i < level ? active : "rgba(255,255,255,0.18)",
            transform: `scale(${i < level ? fill : 1})`,
            border: "2px solid rgba(255,255,255,0.35)",
          }}
        />
      ))}
    </div>
  );
  return (
    <div style={{ display: "flex", gap: 34 * scale, alignItems: "center" }}>
      {dial("BALANCE", mode.balance, BRAND.purpleFrom)}
      {dial("VARIETY", mode.variety, "#34d399")}
      <div
        style={{
          fontFamily: FONT_STACK,
          fontWeight: 900,
          fontSize: 20 * scale,
          letterSpacing: 2,
          color: mode.rated ? BRAND.gold : "rgba(255,255,255,0.45)",
          background: mode.rated
            ? "rgba(255,216,107,0.15)"
            : "rgba(255,255,255,0.08)",
          border: `2px solid ${mode.rated ? BRAND.gold : "rgba(255,255,255,0.25)"}`,
          borderRadius: 999,
          padding: `${4 * scale}px ${16 * scale}px`,
          transform: `scale(${fill})`,
        }}
      >
        {mode.rated ? "🔥 RATED" : "UNRATED"}
      </div>
    </div>
  );
};

/** One mode beat: queue strip → chips drafted into Team A / Team B. */
const ModeBeat: React.FC<{
  aspect: AdProps["aspect"];
  mode: Mode;
}> = ({ aspect, mode }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const lay = layoutFor(aspect);
  const s = lay.fontScale;

  const titleIn = spring({
    frame,
    fps,
    config: { damping: 13, stiffness: 170 },
  });
  const nameIn = spring({
    frame: frame - 8,
    fps,
    config: { damping: 12, stiffness: 190 },
  });
  // Pro Pick: sort fully settles (~f64), hold the sorted grid, then draft.
  const DRAFT = mode.poolSkip ? 74 : 30;
  const chipSize = 56 * s;
  const chipGap = 14 * s;
  const chipW = 196 * s; // fixed chip block width — pitch for lane slides

  const aRating = teamRating(mode.teamA);
  const bRating = teamRating(mode.teamB);
  const maxR = Math.max(aRating, bRating, 1);

  return (
    <AbsoluteFill
      style={{
        padding: lay.pad,
        justifyContent: "center",
        alignItems: "center",
        gap: 34 * s,
      }}
    >
      {/* Mood question → mode name → tagline */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 14 * s,
        }}
      >
        <div
          style={{
            fontFamily: FONT_STACK,
            fontWeight: 800,
            fontSize: 40 * s,
            color: BRAND.gold,
            letterSpacing: 1,
            textShadow: "0 2px 14px rgba(0,0,0,0.3)",
            transform: `scale(${0.85 + titleIn * 0.15})`,
            opacity: titleIn,
          }}
        >
          {mode.mood}
        </div>
        <div
          style={{
            fontFamily: FONT_STACK,
            fontWeight: 900,
            fontSize: 74 * s,
            color: "#fff",
            letterSpacing: -1,
            textShadow: "0 4px 30px rgba(0,0,0,0.35)",
            transform: `scale(${0.85 + nameIn * 0.15})`,
            opacity: nameIn,
          }}
        >
          {mode.name}
        </div>
        <div style={{ opacity: nameIn }}>
          <Dials mode={mode} scale={s} startFrame={10} />
        </div>
      </div>

      {/* Queue lanes — the app's real sections: GENERAL / WINNERS / LOSERS.
          Drafted chips lift out; the rest slide left to close the line. */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 10 * s,
          padding: `${12 * s}px ${18 * s}px`,
          background: "rgba(255,255,255,0.08)",
          borderRadius: 26 * s,
          border: "2px dashed rgba(255,255,255,0.2)",
        }}
      >
        {(mode.poolSkip ? POOL_LANE : LANES).map((lane) => {
          const feeding = lane.idxs.some((i) => mode.pick.includes(i));
          return (
            <div
              key={lane.label}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 12 * s,
                opacity: feeding || frame < DRAFT ? 1 : 0.6,
              }}
            >
              <div
                style={{
                  fontFamily: FONT_STACK,
                  fontWeight: 900,
                  fontSize: 16 * s,
                  letterSpacing: 1.5,
                  color: lane.color,
                  minWidth: 190 * s,
                  flexShrink: 0,
                  display: "flex",
                  flexDirection: "column",
                  gap: 3 * s,
                }}
              >
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 4 * s,
                    whiteSpace: "nowrap",
                  }}
                >
                  <span>{lane.icon}</span>
                  <span>{lane.label}</span>
                </div>
                {/* Pro Pick stage guide — the beat runs as a strict
                    sequence: queue order → sorted by rating → top 4 drafted */}
                {mode.poolSkip && (
                  <div
                    style={{
                      fontWeight: 800,
                      fontSize: 15 * s,
                      letterSpacing: 1,
                      color:
                        frame >= DRAFT ? BRAND.gold : "rgba(255,255,255,0.65)",
                    }}
                  >
                    {frame < 16
                      ? "① queue order"
                      : frame < DRAFT
                        ? "② sorted by rating"
                        : "③ top 4 → drafted"}
                  </div>
                )}
              </div>
              <div
                style={{
                  display: "flex",
                  gap: chipGap,
                  position: "relative",
                  // Pro Pick's single pool wraps to two rows — top-rated
                  // row drafts away, lower-rated row stays queued.
                  ...(mode.poolSkip
                    ? {
                        flexWrap: "wrap" as const,
                        maxWidth: POOL_COLS * (chipW + chipGap),
                      }
                    : {}),
                }}
              >
                {lane.idxs.map((qi, li) => {
                  const p = QUEUE[qi];
                  const picked = mode.pick.includes(qi);
                  // Pro Pick sequence: (1) queue order shown briefly,
                  // (2) organized re-sort — each chip dims out, snaps to
                  // its rating-ranked slot while invisible, fades back.
                  // Grid never visibly breaks; no crisscrossing paths.
                  // (3) top row drafts at DRAFT.
                  const reorderT = mode.poolSkip
                    ? interpolate(frame, [18 + li * 2, 36 + li * 2], [0, 1], {
                        extrapolateLeft: "clamp",
                        extrapolateRight: "clamp",
                      })
                    : 0;
                  const target = mode.poolSkip ? POOL_SORTED.indexOf(qi) : li;
                  const rowPitch = chipSize * 1.24 + chipGap;
                  const snap = reorderT >= 0.5 ? 1 : 0;
                  const sortX =
                    ((target % POOL_COLS) - (li % POOL_COLS)) *
                    (chipW + chipGap) *
                    snap;
                  const sortY =
                    (Math.floor(target / POOL_COLS) -
                      Math.floor(li / POOL_COLS)) *
                    rowPitch *
                    snap;
                  // dip to near-invisible mid-reorder so the teleport reads
                  // as a clean re-sort, not a fly-across
                  const reorderFade =
                    0.85 - 0.72 * Math.sin(Math.PI * reorderT);
                  // FIFO movement: drafted chips leave, the line slides
                  // forward — shift = drafted chips ahead within this lane.
                  const ahead = lane.idxs
                    .slice(0, li)
                    .filter((i) => mode.pick.includes(i)).length;
                  // pool chips already land in their sorted grid slots —
                  // the picked top row clears as one block, no compaction
                  const slide =
                    picked || mode.poolSkip
                      ? 0
                      : spring({
                          frame: frame - DRAFT + 2,
                          fps,
                          config: { damping: 16, stiffness: 170 },
                        });
                  const slideX = -ahead * (chipW + chipGap) * slide;
                  // Pro Pick: picked chips lift out of the pool right at draft
                  const jump =
                    mode.poolSkip && picked
                      ? interpolate(
                          frame,
                          [DRAFT - 4, DRAFT + 4],
                          [0, -18 * s],
                          {
                            extrapolateLeft: "clamp",
                            extrapolateRight: "clamp",
                            easing: (t) => t * (2 - t),
                          },
                        )
                      : 0;
                  const gone = picked
                    ? interpolate(frame, [DRAFT, DRAFT + 14], [1, 0], {
                        extrapolateLeft: "clamp",
                        extrapolateRight: "clamp",
                      })
                    : 1;
                  return (
                    <div
                      key={p.name}
                      style={{
                        transform: `translateX(${sortX + slideX}px) translateY(${sortY + jump}px) scale(${0.9 + gone * 0.1})`,
                        opacity: picked ? gone : reorderFade,
                        position: "relative",
                        zIndex: picked ? 2 : 1,
                      }}
                    >
                      <PlayerChip
                        name={p.name}
                        skill={p.skill}
                        rating={p.rating}
                        size={chipSize}
                        width={chipW}
                      />
                      {/* rank badge appears once sorted into place */}
                      {mode.poolSkip && reorderT > 0.95 && (
                        <div
                          style={{
                            position: "absolute",
                            top: -8 * s,
                            right: -4 * s,
                            fontFamily: FONT_STACK,
                            fontWeight: 900,
                            fontSize: 15 * s,
                            color: BRAND.gold,
                            background: "rgba(0,0,0,0.55)",
                            borderRadius: 999,
                            padding: `${1 * s}px ${8 * s}px`,
                          }}
                        >
                          #{target + 1}
                        </div>
                      )}
                    </div>
                  );
                })}
                {/* "played together" link lines — drawn for variety-aware
                    modes, severed when the draft splits the pair */}
                {mode.showLinks &&
                  lane.idxs.map((qi, li) => {
                    const p = QUEUE[qi];
                    const tIdx =
                      p.linkTo == null ? -1 : lane.idxs.indexOf(p.linkTo);
                    if (p.linkTo == null || tIdx <= li || tIdx < 0) return null;
                    const x1 = li * (chipW + chipGap) + chipW / 2;
                    const x2 = tIdx * (chipW + chipGap) + chipW / 2;
                    const sever = interpolate(
                      frame,
                      [DRAFT + 2, DRAFT + 12],
                      [1, 0],
                      {
                        extrapolateLeft: "clamp",
                        extrapolateRight: "clamp",
                      },
                    );
                    return (
                      <svg
                        key={`${qi}-${p.linkTo}`}
                        style={{
                          position: "absolute",
                          left: 0,
                          top: 0,
                          overflow: "visible",
                          pointerEvents: "none",
                        }}
                      >
                        <line
                          x1={x1}
                          y1={-14 * s}
                          x2={x2}
                          y2={-14 * s}
                          stroke="#34d399"
                          strokeWidth={3 * s}
                          strokeDasharray={`${8 * s} ${8 * s}`}
                          opacity={sever * 0.9}
                        />
                      </svg>
                    );
                  })}
              </div>
            </div>
          );
        })}
      </div>

      {/* Teams — drafted chips spring in staggered, rating bars level out */}
      <div
        style={{
          display: "flex",
          gap: 46 * s,
          alignItems: "stretch",
        }}
      >
        {(["teamA", "teamB"] as const).map((tk, ti) => {
          const team = mode[tk];
          const rating = teamRating(team);
          return (
            <div
              key={tk}
              style={{
                background: "rgba(255,255,255,0.95)",
                borderRadius: 22 * s,
                padding: `${18 * s}px ${26 * s}px`,
                minWidth: lay.isVertical ? 400 * s : 380 * s,
                boxShadow: "0 14px 40px rgba(0,0,0,0.25)",
                display: "flex",
                flexDirection: "column",
                gap: 12 * s,
              }}
            >
              <div
                style={{
                  fontFamily: FONT_STACK,
                  fontWeight: 900,
                  fontSize: 22 * s,
                  color: ti === 0 ? BRAND.purpleFrom : BRAND.purpleTo,
                  letterSpacing: 2,
                  display: "flex",
                  justifyContent: "space-between",
                }}
              >
                <span>TEAM {ti === 0 ? "A" : "B"}</span>
                <span style={{ color: BRAND.ink }}>{rating.toFixed(1)}</span>
              </div>
              {team.map((qi, k) => {
                const in_ = spring({
                  frame: frame - DRAFT - 8 - k * 6 - ti * 4,
                  fps,
                  config: { damping: 12, stiffness: 200 },
                });
                return (
                  <div
                    key={QUEUE[qi].name}
                    style={{
                      transform: `translateY(${(1 - in_) * 24 * s}px) scale(${0.9 + in_ * 0.1})`,
                      opacity: in_,
                    }}
                  >
                    <PlayerChip
                      name={QUEUE[qi].name}
                      skill={QUEUE[qi].skill}
                      rating={QUEUE[qi].rating}
                      size={44 * s}
                    />
                  </div>
                );
              })}
              {/* rating bar — evens out across teams on balance modes */}
              <div
                style={{
                  height: 8 * s,
                  borderRadius: 999,
                  background: "rgba(0,0,0,0.08)",
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${(rating / maxR) * 100}%`,
                    background: ti === 0 ? BRAND.purpleFrom : BRAND.purpleTo,
                    borderRadius: 999,
                    transform: `scaleX(${spring({
                      frame: frame - DRAFT - 20,
                      fps,
                      config: { damping: 20, stiffness: 120 },
                    })})`,
                    transformOrigin: "left",
                  }}
                />
              </div>
            </div>
          );
        })}
      </div>

      {/* Pro Pick callout — the only mode that skips the line */}
      {mode.poolSkip && (
        <div
          style={{
            fontFamily: FONT_STACK,
            fontWeight: 800,
            fontSize: 26 * s,
            color: "#fff",
            background: "rgba(255,216,107,0.18)",
            border: `2px solid ${BRAND.gold}`,
            borderRadius: 999,
            padding: `${8 * s}px ${24 * s}px`,
            opacity: interpolate(frame, [DRAFT + 22, DRAFT + 34], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }),
          }}
        >
          ⚡ ignores the lanes — top rated first
        </div>
      )}
    </AbsoluteFill>
  );
};

export const ModesAd: React.FC<AdProps> = ({ aspect, voiceoverFile }) => {
  const lay = layoutFor(aspect);
  const { durationInFrames } = useVideoConfig();
  // Pro Pick gets a longer beat — it stages three steps (queue order →
  // rating sort → top-4 draft) instead of one.
  const beatLen = (m: Mode) => (m.poolSkip ? 145 : 105);
  const modesStart = 90;
  let off = modesStart;
  const seqs = MODES.map((m) => {
    const from = off;
    off += beatLen(m);
    return { m, from, dur: beatLen(m) };
  });
  const outroStart = off;
  return (
    <AbsoluteFill>
      <BrandBackground />
      {/* Hook */}
      <Sequence durationInFrames={modesStart}>
        <AbsoluteFill
          style={{
            justifyContent: "center",
            alignItems: "center",
            gap: 20 * lay.fontScale,
          }}
        >
          <Caption
            text="Same queue."
            size={72 * lay.fontScale}
            align="center"
          />
          <Caption
            text="Different vibes."
            size={72 * lay.fontScale}
            tone="gold"
            align="center"
            from={18}
          />
        </AbsoluteFill>
      </Sequence>
      {/* One beat per mode — same queue, different draft */}
      {seqs.map(({ m, from, dur }) => (
        <Sequence key={m.key} from={from} durationInFrames={dur}>
          <ModeBeat aspect={aspect} mode={m} />
        </Sequence>
      ))}
      {/* Outro */}
      <Sequence
        from={outroStart}
        durationInFrames={durationInFrames - outroStart}
      >
        <AbsoluteFill
          style={{
            justifyContent: "center",
            alignItems: "center",
            gap: 26 * lay.fontScale,
          }}
        >
          <Caption
            text="One queue. Your vibe."
            size={34 * lay.fontScale}
            tone="gold"
          />
          <AdCtaOutro
            tagline="Set the mode. The algorithm does the rest."
            cta="Run your club free"
            scale={lay.fontScale}
          />
        </AbsoluteFill>
      </Sequence>
      {/* SFX — one accent per mode change + outro */}
      {seqs.map(({ from }, i) => (
        <Sfx key={i} at={from} file="whoosh" volume={0.5} />
      ))}
      <Sfx at={outroStart} file="win" volume={0.8} />
      <AdAudio lines={VO_LINES} voiceoverFile={voiceoverFile} />
    </AbsoluteFill>
  );
};
